<?php
declare(strict_types=1); require_once __DIR__.'/server/includes/bootstrap.php'; require_once __DIR__.'/server/includes/view.php'; $token=trim((string)($_GET['token']??$_POST['token']??'')); $error=''; $valid=false; $row=null;
if(strlen($token)===64 && ctype_xdigit($token)) { $q=$pdo->prepare('SELECT pr.id,pr.user_id FROM password_resets pr JOIN users u ON u.id=pr.user_id WHERE pr.token_hash=? AND pr.used_at IS NULL AND pr.expires_at>NOW() AND u.status=\'active\' LIMIT 1'); $q->execute([hash('sha256',$token)]); $row=$q->fetch(); $valid=(bool)$row; }
if($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); if(!$valid) $error='This reset link is invalid or expired. Request another one.'; else { $p=(string)($_POST['password']??''); $c=(string)($_POST['confirm_password']??''); if(!valid_password($p)||$p!==$c)$error='Passwords must match and contain at least 6 characters.'; else { $pdo->beginTransaction(); try { $pdo->prepare('UPDATE users SET password_hash=?,must_change_password=0 WHERE id=?')->execute([password_hash($p,PASSWORD_DEFAULT),(int)$row['user_id']]); $pdo->prepare('UPDATE password_resets SET used_at=NOW() WHERE id=?')->execute([(int)$row['id']]); $pdo->commit(); audit($pdo,(int)$row['user_id'],'PASSWORD_RESET','Password reset completed'); flash('success','Password updated. You can now log in.'); redirect('login.php'); } catch(Throwable $ex) { if($pdo->inTransaction())$pdo->rollBack(); $error='Could not update password. Request a new reset link.'; } } } }
page_header($config,null,'Set a new password'); ?><section class="auth-wrap"><div class="auth-card"><div class="eyebrow">One-time secure link</div><h1>Set a new password</h1><?php if($error): ?><div class="flash error"><?=e($error)?></div><?php endif; ?><?php if(!$valid): ?><p>This link is not available or has expired. <a href="forgot.php">Request a new password reset</a>.</p><?php else: ?><p>Choose a new password. The link will be invalid after you use it.</p><form method="post"><?=csrf_field()?><input type="hidden" name="token" value="<?=e($token)?>"><label class="field">New password<input type="password" name="password" minlength="6" autocomplete="new-password" required></label><label class="field">Confirm new password<input type="password" name="confirm_password" minlength="6" autocomplete="new-password" required></label><button class="btn gold" type="submit">Save new password</button></form><?php endif; ?></div></section><?php page_footer(); ?>